\begin{ex}%[6H4N2]
\immini[thm]{
Nêu tên đỉnh, cạnh, đường chéo, hai cạnh đối của hình chữ nhật  ${IJQK}$
}{
\begin{tikzpicture}
    % Các đỉnh của hình chữ nhật
    % Các đỉnh của hình chữ nhật
    \coordinate [label=below left:{$I$}] (E) at (0, 0);
    \coordinate [label=above left:{$J$}] (F) at (0, 3);
    \coordinate [label=above right:{$Q$}] (H) at (5, 3);
    \coordinate [label=below right:{$K$}] (G) at (5, 0);
    % Vẽ hình chữ nhật
    \draw[thick] (E) -- (F) -- (G) -- (H) -- cycle;

    % Vẽ các đường chéo
    \draw[thick] (E) -- (G);
    \draw[thick] (F) -- (H);

    % Các điểm
    \fill (E) circle (2pt);
    \fill (F) circle (2pt);
    \fill (H) circle (2pt);
    \fill (G) circle (2pt);
\end{tikzpicture}
}
\loigiai{
Đỉnh ${I,J,Q,K}$\\
Cạnh ${IJ}$, ${JQ}$, ${QK}$, ${IK}$\\
Đường chéo ${IQ}$, ${JK}$\\
Hai cạnh đối là ${IJ}$, ${QK}$ và ${QJ}$, ${IK}$
}\end{ex}

